   148				toolName: parsed.toolName,
   149				data: parsed.data,
   150				viewState: boundedMcpAppViewState(parsed.viewState),
   151				...(typeof parsed.bindingKey === "string" &&
   152				/^[a-f0-9]{64}$/.test(parsed.bindingKey)
   153					? { bindingKey: parsed.bindingKey }
   154					: {}),
   155			};
   156		} catch {
   157			return null;
   158		}
   159	}
   160	
   161	function serializeSnapshot(payload: SnapshotPayload): {
   162		body: string;
   163		plaintextBytes: number;
   164	} | null {
   165		const plaintext = JSON.stringify(payload);
   166		const plaintextBytes = Buffer.byteLength(plaintext, "utf8");
   167		if (plaintextBytes === 0 || plaintextBytes > MCP_APP_RESULT_MAX_BYTES)
   168			return null;
   169		return { body: encrypt(plaintext), plaintextBytes };
   170	}
   171	
   172	export async function storeMcpAppResultSnapshot(args: {
   173		ctx: ToolContext;
   174		toolCallId: unknown;
